namespace docking.action;




using docking;

public abstract class ToggleDockingAction : DockingAction, ToggleDockingActionIf {
	private bool isSelected;

	public ToggleDockingAction(string name, string owner) : base(name, owner)
    {
	}

	public ToggleDockingAction(string name, string owner, KeyBindingType keyBindingType) : base(name, owner, keyBindingType)
    {
	}

	public ToggleDockingAction(string name, string owner, bool supportsKeyBindings) : base(name, owner, supportsKeyBindings)
    {
	}

	/* @Override */
	public bool isSelected() {
		return isSelected;
	}

	/* @Override */
	public void setSelected(bool newValue) {
		if (isSelected == newValue) {
			return;
		}
		isSelected = newValue;
		firePropertyChanged(SELECTED_STATE_PROPERTY, !isSelected, isSelected);
	}

	/* @Override */
	protected JButton doCreateButton() {
		EmptyBorderToggleButton button = new EmptyBorderToggleButton();
		button.setSelected(isSelected);
		return button;
	}

	/* @Override */
	protected JMenuItem doCreateMenuItem() {
		return new DockingCheckBoxMenuItem(isSelected);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		// defined by subclasses
	}

}
